def presentable(issues):
    # A partial certification finding is routed with the packet immediately.
    # Other unresolved work (including absent CD dispositions) still blocks.
    return all(item['element'] == 'certification' and item['kind'] == 'finding' for item in issues)


def decision_conditions(doc):
    """Read explicit dated conditions, preserving source wording and due dates."""
    section = False
    conditions, failures = [], []
    for line in doc['text'].splitlines():
        if line.startswith('## '):
            section = 'condition' in line.casefold()
            continue
        if section and re.match(r'^[-*] ', line.strip()):
            text = line.strip()[2:].strip()
            dates = re.findall(r'\b\d{4}-\d{2}-\d{2}\b', text)
            if len(dates) != 1:
                failures.append('Condition lacks one unambiguous recorded due date: ' + text)
            else:
                conditions.append({'condition': text, 'due': dates[0]})
    if doc['fields'].get('outcome') == 'approved-with-conditions' and not conditions:
        failures.append('Conditional approval lacks parseable explicitly dated conditions; retain record for MSP review')
    return conditions, failures


def assess(app, tables, documents, as_of, reg, before=False):
    from .evidence import evaluate_replies
    from .privileges import evaluate_privileges
    # The previous day is used only for receipt/revision/doc cutoff; lookups keep
    # their explicit decision-day exception in licensed().
    receipt_cutoff = (date.fromisoformat(as_of) - timedelta(days=1)).isoformat() if before else as_of
    docs = for_application(documents, app['application_id'], as_of, before)
    evidence = evaluate_replies(app, tables, as_of, before, documents=docs)
    licence = licensed(app, tables, docs, as_of)
    gaps = gaps_for(app, tables, docs, receipt_cutoff, evidence['entry_checks'])
    intake_result = intake(app, tables, docs, receipt_cutoff, reg, gaps, evidence['entry_checks'])
    privileges = evaluate_privileges(app, tables, as_of, reg, evidence['entry_checks'], before)
    issues = evidence['issues'] + licence['issues'] + gaps['issues'] + intake_result['issues'] + privileges['issues']
    for doc in docs:
        for conflict in document_conflicts(doc, app):
            issues.append(issue('reconciliation', 'discrepancy', conflict, 'B39', [doc['path']], 'Applicant'))
    attempts = [r for r in tables['verification-attempts'] if r['application_id'] == app['application_id'] and r['attempt_date'] <= receipt_cutoff]
    for entry in evidence['entry_checks']:
        matching = [r for r in attempts if r['subject_ref'] == entry['entry_id']]
        if entry.get('in_scope') and not entry.get('accepted_reply_ids') and len(matching) >= 3:
            is_employment = entry.get('declared', {}).get('entry_type') in {'employment', 'affiliation', 'teaching'}
            issues.append(issue('experience' if is_employment else 'education', 'outstanding', f"{entry['entry_id']}: {len(matching)} recorded attempts without admissible resolution; continue requests, nonresponse is not impossibility." + (' Preserve the nonresponse red flag for leadership.' if is_employment else ''), 'B08', [row_ref('verification-attempts', r) for r in matching]))
    actions, seen = [], set()
    for item in issues:
        detail, due = item['detail'], item['due']
        if (not intake_result['release_present'] and item['element'] in ELEMENTS
                and item['owner'] == 'Medical Services Professional'
                and any(term in detail.casefold() for term in ('request', 'follow', 'obtain admissible verification', 'obtain admissible certification verification'))):
            detail = 'Hold verification outreach until signed release; ' + detail
            due = None
        key = (detail, item['owner'], due)
        if key not in seen:
            actions.append({'item': detail, 'owner': item['owner'], 'due': due})
            seen.add(key)
    return {'application': app, 'as_of': as_of, 'historical_before_decision': before,
            'elements': element_states(issues), 'packet_presentable': presentable(issues),
            'intake': intake_result, 'entry_checks': evidence['entry_checks'], 'peer_checks': evidence['peer_checks'],
            'licensure': licence, 'gaps': gaps, 'privileges': privileges, 'issues': issues,
            'attempts': attempts, 'action_queue': actions, 'document_paths': [d['path'] for d in docs]}


def check_decision(doc, app, assessed, reg, prior):
    f = doc['fields']
    failures = []
    body, outcome, when = f.get('body', ''), f.get('outcome', ''), f.get('decision_date', '')
    if outcome not in reg['bodies'].get(body, []):
        failures.append('1 body/outcome authority: body is not authorized for the recorded outcome')
    roles = [r for r in reg['roles'] if person(r['name']) == person(f.get('signatory', '')) and normalized(r['role']) == normalized(f.get('role', ''))]
    authorized = any((not r['start'] or r['start'] <= when <= r['end']) and body in r['role'] for r in roles)
    if any(r['role'] == 'Vice-Chair, Governing Body' for r in roles) and when < reg['designation_date']:
        authorized = False  # Designation boundary explicitly unresolved in A/Q10.
    signed = next((line for line in doc['text'].splitlines() if line.startswith('Signed:')), '')
    if not authorized or not signed or person(f.get('signatory', '')) not in person(signed) or when not in signed:
        failures.append('2 signatory authority: role, term, designation or signed record not established by roster/evidence')
    if f.get('application') != app['application_id'] or f.get('revision') != app['revision']:
        failures.append('3 applicant/revision: decision does not match the applicable numbered revision')
    if not assessed['packet_presentable'] or app['received_date'] >= when:
        failures.append('4 prior presentability: required evidence/work was not resolved before this decision for its exact revision')
    if outcome not in {'recommended', 'approved'} and not f.get('reason'):
        failures.append('5 outcome/reason: this outcome requires a recorded reason')
    codes = [x.strip() for x in f.get('privileges', '').split(';') if x.strip()]
    if outcome in {'recommended', 'approved', 'approved-with-conditions'} and (not codes or any(x not in reg['groups'] for x in codes)):
        failures.append('5 outcome/reason: privilege codes absent or not published in the criteria')
    if f.get('criteria_version') != reg['criteria_version'] or when < reg['criteria_effective']:
        failures.append('6 criteria version: the recorded version is not established in force on decision date')
    if body == 'Governing Body' and outcome in {'approved', 'approved-with-conditions'}:
        eligible = [p for p in prior if p['admitted'] and p['fields'].get('body') == 'Executive Committee of the Medical Staff' and p['fields'].get('outcome') == 'recommended' and p['fields'].get('revision') == f.get('revision') and p['fields'].get('application') == f.get('application') and p['fields'].get('decision_date', '') < when]
        if not eligible:
            failures.append('7 recommendation: no separately valid prior Executive Committee recommendation for this revision')
    gb_prior = [p for p in prior if p['admitted'] and p['fields'].get('body') == 'Governing Body' and p['fields'].get('revision') == f.get('revision')]
    if body == 'Governing Body' and gb_prior and f.get('supersedes') != gb_prior[-1]['fields'].get('decision_id'):
        failures.append('8 duplicate/supersession: later Governing Body record lacks required explicit supersession')
    if outcome == 'approved-with-conditions':
        failures.extend('Conditions: ' + x for x in decision_conditions(doc)[1])
    if f.get('effective_date') and f['effective_date'] < when:
        failures.append('Effective-date backdate is unresolved under Q05; no activation is inferred')
    if document_conflicts(doc, app):
        failures.extend('Source conflict: ' + x for x in document_conflicts(doc, app))
    return failures


def terminal_status(docs, app, reg):
    for d in reversed(docs):
        if document_conflicts(d, app):
            continue
        title, text, f = d['title'].casefold(), d['text'].casefold(), d['fields']
        if 'withdraw' in title and person(f.get('from', '')) in {person(' '.join([app['first_name'], app['middle_name'], app['last_name']])), person(' '.join([app['first_name'], app['last_name']]))} and 'withdraw' in text:
            return 'withdrawn', d['path']
        if 'discontinu' in title:
            cd = next(r for r in reg['roles'] if r['role'] == 'Clinical Director')
            signatory = f.get('signatory', f.get('from', ''))
            if person(signatory) == person(cd['name']) and cd['start'] <= d['index']['date'] <= cd['end']:
                return 'discontinued', d['path']
    return None, None


"""Reconcile changed declarations against facts in retained verification (B04/B23).

Procedure §§2, 8 and 11 require entry-specific reconciliation, without a new
request-date condition. This helper assesses facts only. Its caller must still
check source authority, receipt dates, reply outcome, dates and open disputes.
"""

import re


def _normal(value):
    return " ".join(str(value or "").casefold().split())


def _role_facts(reply):
    facts = []
    if reply.get("verified_role"):
        facts.append(("verified_role", reply["verified_role"]))
    credential = reply.get("verified_credential", "")
    match = re.fullmatch(r"(Employment|Affiliation|Degree|Residency|Fellowship|Internship)\s*[—–-]\s*(.+)", credential, re.IGNORECASE)
    if match:
        kind, value = match.groups()
        if kind.casefold() in {"residency", "fellowship", "internship"}:
            if not _normal(value).endswith(kind.casefold()):
                value += " " + kind
        facts.append(("verified_credential", value))
    return facts


def verified_role(reply: dict) -> str | None:
    """Return one unambiguous normalized role from structured reply evidence.

    Case and whitespace are normalized. ``Degree — Doctor of Medicine`` yields
    ``doctor of medicine``; ``Residency — Family Medicine`` yields
    ``family medicine residency`` (likewise fellowship/internship). Employment
    and affiliation prefixes are removed. Explicit ``verified_role`` is also
    considered; if it contradicts the credential label, return None. Unlabelled
    free text and notes yield no inferred role. This is a fact extraction helper,
    not source acceptance, currency or completeness approval.
    """
    values = {_normal(value) for _, value in _role_facts(reply)}
    return values.pop() if len(values) == 1 else None


def assess_revision(entry: dict, histories: list[dict], reply: dict) -> dict:
    """Return ``changed_fields``, ``missing_facts`` and ``conflicts``.

    ``entry`` is one current declared-history row. ``histories`` may contain
    multiple applications/revisions; only this application/entry's strictly
    lower revisions are compared. Each field uses its most recent differing
    prior value, so a later contact-only revision cannot hide an unsupported
    earlier role change. No predecessor means no revision changes to reconcile
    (the caller still verifies the original entry).

    ``changed_fields`` maps each changed nonidentity field to previous/current
    raw values, their revision numbers and an ``evidence`` list. Each evidence
    item records a reply field, extracted value and source reference.
    ``missing_facts`` and ``conflicts`` are lists of dictionaries containing
    field, declared value, reason and source_refs; conflicts also retain the
    verified value. Empty lists mean no additional revision-specific hold,
    never that the entire entry or reply has been verified.

    Contact changes are traced without invalidating credential facts. Dates
    are traced for the caller's existing date comparison. Changed organization,
    role, supervisor and other substantive fields need corresponding evidence.
    Explicit supplemental ``verified_role``/``verified_supervisor`` fields are
    supported. Clear credential labels can establish role; notes are preserved
    by the caller and are never mined for authority or guessed facts here.
    Request/receipt dates do not decide whether a fact matches a declaration.
    """
    revision = int(entry["revision"])
    prior = [row for row in histories
             if row.get("application_id") == entry.get("application_id")
             and row.get("entry_id") == entry.get("entry_id")
             and int(row["revision"]) < revision]
    result = {"changed_fields": {}, "missing_facts": [], "conflicts": []}
    if not prior:
        return result
    declaration_ref = "declared-history.csv#" + entry["entry_id"]
    reply_ref = "verification-replies.csv#" + reply.get("reply_id", "<unidentified>")
    refs = [declaration_ref, reply_ref]
    fields = set(entry).union(*(set(row) for row in prior))
    for field in sorted(fields):
        if field in {"application_id", "entry_id", "revision"}:
            continue
        different = [row for row in prior if row.get(field) != entry.get(field)]
        if not different:
            continue
        previous = max(different, key=lambda row: int(row["revision"]))
        current = entry.get(field)
        change = {"previous": previous.get(field), "current": current,
                  "previous_revision": int(previous["revision"]), "current_revision": revision,
                  "evidence": []}
        result["changed_fields"][field] = change
        if field.startswith("contact_") or field in {"verification_contact", "from_date", "to_date"}:
            continue
        facts = []
        if field == "role":
            facts = _role_facts(reply)
        elif field in {"supervisor", "supervisor_name"}:
            facts = [(key, reply[key]) for key in ("verified_supervisor", "verified_supervisor_name") if reply.get(key)]
        elif field == "organization":
            if reply.get("verified_organization"):
                facts.append(("verified_organization", reply["verified_organization"]))
            attester = reply.get("attester_organization", "")
            # A transmitting primary office can identify its own institution;
            # an equivalent/CVO's name alone cannot identify the verified one.
            if (_normal(attester) in {_normal(current), _normal(previous.get(field))}
                    and _normal(attester) and _normal(attester) in _normal(reply.get("received_from", ""))):
                facts.append(("attester_organization", attester))
        else:
            key = "verified_" + field
            if reply.get(key) not in (None, ""):
                facts.append((key, reply[key]))
        change["evidence"] = [{"field": key, "value": value, "source_ref": reply_ref} for key, value in facts]
        if not facts:
            result["missing_facts"].append({"field": field, "declared": current,
                "reason": "Retained reply does not establish the revised material fact",
                "source_refs": refs})
        for key, value in facts:
            if _normal(value) != _normal(current):
                result["conflicts"].append({"field": field, "declared": current,
                    "verified": value, "reason": f"Revised declaration differs from reply field {key}",
                    "source_refs": refs})
    return result
"""Conservative, source-preserving education, experience and peer checks."""

import re
from datetime import date

from .dates import (UnsupportedBoundary, first_received_window, overlaps_window,
                    peer_current, peer_followups, worked_recently)
from .policy import person
from .revisions import assess_revision


EDUCATION = {"medical-school", "residency", "fellowship", "internship"}
EQUIVALENTS = {
    "ecfmg", "educational commission for foreign medical graduates",
    "fcvs", "fsmb fcvs", "federation credentials verification service",
    "ama physician profile", "american medical association physician profile",
    "aoa physician profile", "american osteopathic association physician profile",
    "national student clearinghouse",
}


def _normal(value):
    return " ".join(value.casefold().split())


def _available(row, as_of, before):
    received = row.get("received_date", "")
    return bool(received) and (received < as_of if before else received <= as_of)


def _source_accepted(row, entry, education):
    """Closed source categories; prose notes cannot grant source authority."""
    source = _normal(row.get("received_from", ""))
    role = _normal(row.get("attester_role", ""))
    organization = _normal(row.get("attester_organization", ""))
    employer = _normal(entry.get("organization", ""))
    credential = _normal(row.get("verified_credential", ""))
    material = credential + " " + _normal(row.get("notes", ""))
    if not source or "applicant" in source or any(
        word in material for word in ("photocopy", "certificate image", "diploma copy", "scanned certificate", "copy of the diploma")
    ):
        return False
    # The export identifies transmitting offices separately from individual roles.
    same_org = bool(organization and organization == employer and employer in source)
    if education:
        if source in EQUIVALENTS or organization in EQUIVALENTS and organization in source:
            return True
        if not same_org:
            return False
        if entry["entry_type"] == "medical-school":
            return ("registrar" in source and "registrar" in role) or ("dean" in source and "dean" in role)
        return ("graduate medical education office" in source and any(
            word in role for word in ("programme coordinator", "program coordinator", "director", "gme")
        )) or (any(word in source for word in ("programme director", "program director"))
               and "director" in role)
    if not same_org:
        # CVO authority must name both itself and the represented employer.
        return bool(organization and employer and employer in source and organization in source
                    and "retained" in source and ("cvo" in source or "credentials verification organization" in source))
    return (("medical staff office" in source and "medical staff" in role)
            or ("human resources" in source and ("human resources" in role or "hr" == role))
            or ("authorized" in source and "administrator" in source and "administrator" in role))


def _direct_work(text):
    text = _normal(text)
    if any(term in text for term in ("never worked", "not worked", "have not worked", "did not work", "only know", "membership")):
        return False
    if any(term in text for term in ("worked together", "worked in the same", "work together", "supervised", "directly worked")):
        return True
    return None


def _closure_recorded(attempt):
    """Recognize recorded closure facts, never infer them from silence."""
    if _normal(attempt.get("outcome", "")) in {"institution closed", "school closed", "programme closed", "employer dissolved"}:
        return True
    comment = _normal(attempt.get("comment", ""))
    return bool(re.search(
        r"\b(?:institution|school|programme|program|employer|organization) "
        r"(?:(?:has|is|was) )?(?:permanently )?(?:closed|dissolved)\b", comment))


def _accreditation_fact(text):
    """Recognize explicit facts, never accreditation from credential or source names."""
    text = _normal(text)
    if re.search(r'\b(?:not|never|no longer)\s+(?:currently\s+)?accredited\b|\bunaccredited\b|'
                 r'\baccreditation\s*(?::|is|was)?\s*(?:not|unknown|unverified|pending|revoked|expired)|'
                 r'\b(?:cannot|unable to)\s+(?:confirm|verify)\s+accreditation\b|'
                 r'\bno source establishes accreditation\b', text):
        return False
    for clause in re.split(r'[.;\n]', text):
        if re.search(r'\b(?:not|never|no|cannot|unable|unverified|unknown|pending|revoked|expired|unaccredited|uncertain)\b', clause):
            continue
        if re.search(r'accreditation\s*:\s*(?:currently\s+)?accredited\b|'
                     r'\b(?:school|institution|programme|program|residency|fellowship)\s+is\s+(?:currently\s+)?accredited\b', clause):
            return True
    return False


def _accreditation_denied(text):
    return bool(re.search(r'\b(?:not|never|no longer)\s+(?:currently\s+)?accredited\b|\bunaccredited\b|'
                          r'\baccreditation\s*:\s*(?:revoked|expired)\b', _normal(text)))


def _document_failures(doc, app, as_of, before):
    """Supported labelled evidence must independently bind identity and availability."""
    fields, index = doc.get('fields', {}), doc.get('index', {})
    failures = []
    if fields.get('application') != app['application_id'] or index.get('application_id') != app['application_id']:
        failures.append('Document application identity does not match')
    if fields.get('revision') and fields['revision'] != str(app['revision']):
        failures.append('Document revision does not match')
    if fields.get('applicant'):
        expected = {person(' '.join(app.get(key, '') for key in keys)) for keys in
                    (('first_name', 'middle_name', 'last_name'), ('first_name', 'last_name'))}
        if person(fields['applicant']) not in expected:
            failures.append('Document applicant name does not match')
    if index.get('direction') != 'inbound':
        failures.append('Document is not indexed as received evidence')
    if not doc.get('path') or index.get('document_path') != doc['path']:
        failures.append('Document path is not bound to its correspondence index')
    if index.get('date') != fields.get('received_date'):
        failures.append('Document receipt date conflicts with correspondence index')
    for name, value in (('index date', index.get('date')), ('received date', fields.get('received_date'))):
        try:
            valid = value and date.fromisoformat(value).isoformat() == value
        except ValueError:
            valid = False
        if not valid or value < app['first_received_date'] or (value >= as_of if before else value > as_of):
            failures.append('Document ' + name + ' is outside the verification window or missing')
    return failures


def _accreditation_documents(documents, app, entry, accepted_ids, as_of, before):
    records = []
    for doc in documents:
        fields = doc.get('fields', {})
        if fields.get('entry') != entry['entry_id'] and fields.get('reply') not in accepted_ids:
            continue
        failures = _document_failures(doc, app, as_of, before)
        if fields.get('entry') != entry['entry_id'] or fields.get('reply') not in accepted_ids:
            failures.append('Accreditation supplement is not bound to this entry and an accepted reply')
        source = {key: fields.get(key, '') for key in
                  ('received_from', 'attester_role', 'attester_organization', 'verified_credential')}
        source['notes'] = doc.get('text', '')
        if not _source_accepted(source, entry, True):
            failures.append('Accreditation supplement is not from an accepted official source')
        fact_text = 'Accreditation: ' + fields.get('accreditation', '') + '; ' + doc.get('text', '')
        denied = not failures and _accreditation_denied(fact_text)
        if not _accreditation_fact(fact_text):
            failures.append('Supplement does not state unambiguous accreditation')
        records.append({'path': doc.get('path'), 'accepted': not failures, 'failures': failures, 'denies_accreditation': denied})
    return records


def _peer_return_documents(documents, app, referee, reply, as_of, before):
    records = []
    for doc in documents:
        fields = doc.get('fields', {})
        if fields.get('referee') != referee['referee_id'] and fields.get('reply') != reply['reply_id']:
            continue
        failures = _document_failures(doc, app, as_of, before)
        if fields.get('referee') != referee['referee_id'] or fields.get('reply') != reply['reply_id']:
            failures.append('Return record is not bound to this referee and reply')
        binding_valid = not failures
        if _normal(fields.get('received_from', '')) != _normal(referee['referee_name']):
            failures.append('Return sender is not the named referee')
        if _normal(fields.get('return_method', '')) not in {'secure portal', 'letter', 'fax', 'email'}:
            failures.append('Direct return method is not established')
        returned = fields.get('return_date') or fields.get('received_date')
        if returned != reply['received_date'] or returned > fields.get('received_date', ''):
            failures.append('Return date is not bound to the original reply receipt')
        records.append({'path': doc.get('path'), 'accepted': not failures, 'failures': failures,
                        'applicant_route': binding_valid and 'applicant' in _normal(fields.get('received_from', ''))})
    return records


def evaluate_replies(app: dict, tables: dict, as_of: str, before: bool = False, documents=()) -> dict:
    """Evaluate supplied evidence; do not resolve exceptions or clinical findings.

    ``before`` applies a strict receipt cutoff for historical presentation.
    Raw declaration and reply dictionaries are copied into the result.
    """
    app_id, revision = app["application_id"], int(app["revision"])
    first_received = app["first_received_date"]
    result = {"entry_checks": [], "peer_checks": [], "issues": []}

    def issue(element, kind, detail, rule, refs, due=None, owner="Medical Services Professional"):
        result["issues"].append({"element": element, "kind": kind, "detail": detail,
        result["issues"].append({"element": element, "kind": kind, "detail": detail,
                                 "owner": owner, "due": due, "rule": rule, "source_refs": refs})

    histories = [row for row in tables.get("declared-history", []) if row["application_id"] == app_id]
    current = [row for row in histories if int(row["revision"]) == revision]
    try:
        window = first_received_window(first_received)
    except UnsupportedBoundary as exc:
        window = None
        issue("experience", "outstanding", str(exc), "B14/Q10", ["applications.csv#" + app_id])
    for entry in current:
        education = entry["entry_type"] in EDUCATION
        element = "education" if education else "experience"
        entry_id = entry["entry_id"]
        refs = ["declared-history.csv#" + entry_id]
        in_scope = education or window is None or overlaps_window(
            entry["from_date"], entry.get("to_date") or None, window, as_of)
        rows = [dict(row) for row in tables.get("verification-replies", [])
                if row["application_id"] == app_id and row["entry_id"] == entry_id]
        in_scope = in_scope or any(_available(row, as_of, before) and (
            row.get("outcome") == "confirmed-with-discrepancy"
            or row.get("verified_from", "") != entry.get("from_date", "")
            or row.get("verified_to", "") != entry.get("to_date", "")) for row in rows)
        check = {"entry_id": entry_id, "accepted_reply_ids": [], "failures": [],
                 "declared": dict(entry), "verification_rows": rows, "in_scope": in_scope,
                 "dates_verified": False, "accreditation_verified": False if education else None,
                 "revision_mapping": None, "unresolved_discrepancy": False,
                 "secondary_route_candidate": False, "accreditation_source_refs": [],
                 "accreditation_evidence": []}
        attempts = [row for row in tables.get("verification-attempts", [])
                    if row.get("application_id") == app_id and row.get("subject_ref") == entry_id
                    and row.get("attempt_date") and (row["attempt_date"] < as_of if before else row["attempt_date"] <= as_of)]
        check["verification_attempts"] = [dict(row) for row in attempts]
        result["entry_checks"].append(check)
        if not in_scope:
            continue
        check['revision_mapping'] = {}
        for row in rows:
            if not _available(row, as_of, before):
                continue
            failures = []
            if row["received_date"] < first_received:
                failures.append("Reply predates first application receipt")
            mapping = assess_revision(entry, histories, row)
            if mapping['changed_fields']:
                check['revision_mapping'][row['reply_id']] = mapping
            if mapping['missing_facts']:
                failures.append('Reconcile revised facts not established by this retained reply: ' + ', '.join(x['field'] for x in mapping['missing_facts']))
            if mapping['conflicts']:
                check['unresolved_discrepancy'] = True
                failures.append('Revised material facts conflict with retained verification; preserve both for reconciliation')
                issue(element, 'discrepancy', f"{entry_id}: revised facts differ in {row['reply_id']}: {mapping['conflicts']}", 'B04/B05/B23', refs + ['verification-replies.csv#' + row['reply_id']])
            if not _source_accepted(row, entry, education):
                failures.append("Source is not an accepted direct source; MSP must assess any documented impossibility exception")
            if row.get("outcome") not in {"confirmed", "confirmed-with-discrepancy"}:
                failures.append("Reply does not confirm the entry")
            source_refs = refs + ["verification-replies.csv#" + row["reply_id"]]
            conflicts = {key: {"declared": entry.get(declared, ""), "verified": row.get(key, "")}
                         for key, declared in (("verified_from", "from_date"), ("verified_to", "to_date"))
                         if row.get(key, "") != entry.get(declared, "")}
            if conflicts or row.get("outcome") == "confirmed-with-discrepancy":
                check["unresolved_discrepancy"] = True
                failures.append("Verified dates/outcome conflict with declaration; retain both and obtain written reconciliation")
                issue(element, "discrepancy", f"{entry_id}: conflicting verification {row['reply_id']}: {conflicts}; {row.get('notes', '')}", "B04/B05", source_refs)
            check["failures"].extend(f"{row['reply_id']}: {failure}" for failure in failures)
            if failures:
                issue(element, "outstanding", f"{entry_id}: {'; '.join(failures)}", "B06/B07/B23", source_refs)
            else:
                check["accepted_reply_ids"].append(row["reply_id"])
                check["dates_verified"] = True
        if check["unresolved_discrepancy"]:
            check["dates_verified"] = False
        if not check["accepted_reply_ids"]:
            check["failures"].append("No usable verification reply")
            if any(_closure_recorded(attempt) for attempt in attempts):
                check["secondary_route_candidate"] = True
                issue(element, "outstanding", f"{entry_id}: recorded closure requires MSP assessment of documented impossibility and the possible most-recent-affiliation secondary route. Preserve the attempts; a single equivalent's no-record response does not establish that no equivalent holds the record. Obtain the required written verification account and exception determination before acceptance.",
                      "B07", refs + ["verification-attempts.csv#" + row["attempt_id"] for row in attempts])
            else:
                issue(element, "outstanding", f"{entry_id}: obtain admissible verification", "B17" if education else "B14", refs)
        if education:
            check['accreditation_source_refs'] = ['verification-replies.csv#' + row['reply_id']
                for row in rows if row['reply_id'] in check['accepted_reply_ids'] and _accreditation_fact(row.get('notes', ''))]
            check['accreditation_evidence'] = _accreditation_documents(
                documents, app, entry, check['accepted_reply_ids'], as_of, before)
            check['accreditation_source_refs'].extend(record['path'] for record in check['accreditation_evidence'] if record['accepted'])
            denials = ['verification-replies.csv#' + row['reply_id'] for row in rows
                       if row['reply_id'] in check['accepted_reply_ids'] and _accreditation_denied(row.get('notes', ''))]
            denials.extend(record['path'] for record in check['accreditation_evidence'] if record['denies_accreditation'])
            check['accreditation_verified'] = bool(check['accreditation_source_refs']) and not denials
            if denials:
                issue(element, 'discrepancy', f'{entry_id}: source reports absent/ceased accreditation; preserve and reconcile the evidence', 'B05/B40', refs + denials + check['accreditation_source_refs'])
            if not check['accreditation_verified']:
                check["failures"].append("Required accreditation evidence is not established")
                issue(element, "outstanding", f"{entry_id}: required accreditation evidence missing; a dates/credential reply does not establish accreditation", "B17/B40", refs)
        received_rows = [row for row in rows if _available(row, as_of, before)]
        refused = any(row.get("outcome", "").casefold() in {"refused", "refusal", "no response", "nonresponse"} for row in received_rows)
        if not education and not check["accepted_reply_ids"] and len(attempts) >= 3 and (not received_rows or refused):
            issue(element, "finding", f"{entry_id}: affiliation refusal/nonresponse after at least three attempts; preserve attempts and refer for review", "B08", refs + ["verification-attempts.csv#" + row["attempt_id"] for row in attempts])

    referees = [row for row in tables.get("peer-referees", [])
                if row["application_id"] == app_id and int(row["revision"]) == revision]
    for referee in referees:
        referee_id = referee["referee_id"]
        refs = ["peer-referees.csv#" + referee_id]
        replies = [row for row in tables.get("peer-reference-replies", [])
                   if row["application_id"] == app_id and row["referee_id"] == referee_id and _available(row, as_of, before)]
        if not replies:
            check = {"referee_id": referee_id, "reply_id": None, "eligible": None,
                     "provenance_verified": False, "usable": False, "failures": ["No peer reply received"], "reply": None}
            result["peer_checks"].append(check)
            requested = referee.get("first_request_date")
            due = None
            detail = f"{referee_id}: peer reply remains outstanding"
            if requested and requested <= as_of:
                followups = peer_followups(requested)
                check["followup_dates"] = followups
                attempts = sorted([row for row in tables.get("verification-attempts", [])
                    if row.get("application_id") == app_id and row.get("subject_ref") == referee_id
                    and row.get("attempt_date") and row["attempt_date"] > requested
                    and (row["attempt_date"] < as_of if before else row["attempt_date"] <= as_of)],
                    key=lambda row: (row["attempt_date"], row.get("attempt_id", "")))
                fulfilled = []
                for attempt in attempts:
                    if len(fulfilled) < 2 and attempt["attempt_date"] >= followups[len(fulfilled)]:
                        fulfilled.append({"due": followups[len(fulfilled)],
                                          "attempt_id": attempt["attempt_id"],
                                          "attempt_date": attempt["attempt_date"]})
                check["recorded_followups"] = fulfilled
                due = followups[len(fulfilled)] if len(fulfilled) < 2 else None
                if due:
                    detail += "; send the next unrecorded reminder"
                if as_of >= followups[-1]:
                    issue("references", "outstanding", f"{referee_id}: notify applicant and request an additional referee; original request remains open",
                          "B09", refs, followups[-1])
            issue("references", "outstanding", detail, "B09/B10", refs, due)
            continue
        for row in replies:
            failures, eligibility = [], True
            unknown = False
            if row["received_date"] < first_received:
                failures.append("Reply predates first application receipt")
                eligibility = False
            if not row.get("signature_date"):
                unknown = True
                failures.append("Missing signature date")
            else:
                try:
                    if not peer_current(row["signature_date"], as_of):
                        eligibility = False
                        failures.append("Signature is not current on presentation date")
                    if row["signature_date"] > row["received_date"]:
                        eligibility = False
                        failures.append("Signature is after receipt")
                    if not worked_recently(row.get("last_worked_together_end"), row["signature_date"]):
                        eligibility = False
                        failures.append("Last direct work is outside two years at signature or is future dated")
                except UnsupportedBoundary as exc:
                    unknown = True
                    failures.append(str(exc))
            related = row.get("related_or_partner", "")
            if related != "No":
                eligibility = False if related == "Yes" else eligibility
                unknown |= related not in {"Yes", "No"}
                failures.append("Related/spouse/partner status does not establish eligibility")
            if not row.get("referee_specialty_stated"):
                unknown = True
                failures.append("Missing stated discipline")
            elif _normal(row["referee_specialty_stated"]) != _normal(app["discipline"]):
                eligibility = False
                failures.append("Referee is not in the applicant's declared discipline")
            direct = _direct_work(row.get("relationship_stated", ""))
            if direct is not True:
                eligibility = False if direct is False else eligibility
                unknown |= direct is None
                failures.append("Direct work together is not established")
            eligible = False if not eligibility else None if unknown else True
            provenance = _peer_return_documents(documents, app, referee, row, as_of, before)
            provenance_refs = [record['path'] for record in provenance if record['accepted']]
            route_conflicts = [record['path'] for record in provenance if record['applicant_route']]
            provenance_verified = bool(provenance_refs) and not route_conflicts
            if route_conflicts:
                failures.append('Recorded applicant return route requires reconciliation; direct route is not established')
            elif not provenance_refs:
                failures.append("Direct referee-return provenance is not supplied")
            source_refs = refs + ["peer-reference-replies.csv#" + row["reply_id"]]
            result["peer_checks"].append({"referee_id": referee_id, "reply_id": row["reply_id"],
                "eligible": eligible, "provenance_verified": provenance_verified, "usable": eligible is True and provenance_verified,
                "provenance_source_refs": provenance_refs, "provenance_evidence": provenance,
                "failures": failures, "reply": dict(row)})
            if failures:
                issue("references", "outstanding", f"{referee_id}/{row['reply_id']}: {'; '.join(failures)}", "B18/B19/B38/B40", source_refs + provenance_refs)
    usable_referees = {row["referee_id"] for row in result["peer_checks"] if row['usable']}
    if len(usable_referees) < 2:
        issue("references", "outstanding", "At least two eligible current same-discipline peers with verified direct-return provenance are required", "B18/B19/B38", ["applications.csv#" + app_id])
    return result
﻿How this office exports its credentialing records
Larkhollow Community Hospital · Medical Staff Office A note from the Medical Services Professional to whoever automates the initial-appointment file. Written 2026-03-16, alongside the first export.
I run the export from the credentialing database every few weeks and drop it in the shared folder, one sub-folder per export. Here is what you get, what the columns mean, and the three or four things that catch people out.
The export date is the clock
Every batch folder has a README.md that says the export date and the window it covers. That date is the clock for everything in the folder: nothing in a batch happened after its export date. Work the batch as if today were the export date. Do not use the real date you run your tool, and do not carry today's date into an arithmetic that a batch is supposed to settle.
The three exports are 2026-03-16, 2026-04-20 and 2026-05-18. The first one covers everything on file up to and including 2026-03-15, however far back it goes — one application here was first received in 2024. The second and third cover only what changed since the previous one.
The caseload at an export date is every application file the office has received up to that date, however that file ended. A withdrawn or discontinued file stays in the caseload with its final status; a later batch never removes a file, it only adds to what is known about it.
A batch is closed. It never changes.
I never go back and edit an export. If an applicant corrects something, a new revision of the application appears in a later batch and the old one stays exactly where it was. If a board sends a corrected reply, the corrected reply is a new row and the old row stays. If a committee decides something twice, there are two decision records.
So: do not diff a later batch against an earlier one looking for edits. There are none. What a later batch contains is new rows, new documents and new observations.
The files
Thirteen comma-separated exports, and three folders of documents.
File
	One row is
	applications.csv
	an application revision I received in the window
	application-disclosures.csv
	one professional practice question and the applicant's answer
	declared-history.csv
	one history entry the applicant declared
	declared-credentials.csv
	one licence or certification as the applicant described it
	privilege-requests.csv
	one privilege group requested
	licence-lookup-wa.csv
	one Washington credential record from the state board's lookup
	licence-lookup-other-states.csv
	one out-of-state credential record
	certification-replies.csv
	one certifying board's reply
	verification-replies.csv
	one reply about education and training, or about an affiliation or employer
	verification-attempts.csv
	one request I sent
	peer-referees.csv
	one referee named on an application, or supplied later
	peer-reference-replies.csv
	one completed reference form that came back
	correspondence.csv
	one letter, memo or decision record, with the path to the document


Folder
	What is in it
	letters/
	applicants' explanation letters, withdrawals, referee substitutions, and my own written requests for missing items
	dispositions/
	the Clinical Director's recorded dispositions
	decisions/
	Credentials Committee and Executive Committee minutes extracts, and Governing Body approval records
	correspondence.csv is an index. It tells you the documents exist and where they are. It does not tell you what they say — you have to open them.
A file with only a header row means the export ran and there was nothing in that window. That is not the same as a missing file, and it is not an error.
Dates, blanks and columns
* Dates are YYYY-MM-DD. Always. A date range is inclusive at both ends: an entry from_date 2022-01-01, to_date 2022-12-31 covers the 1st of January and the 31st of December. An expiry date is the last day the credential is valid.
* An empty cell means I hold no value for that field. It does not mean zero, it does not mean "no", and it does not mean the answer is unknown-but-probably-fine. Two blanks carry a specific meaning and you should learn them:
   * a blank to_date in declared-history.csv means the entry is current, running to the export date — not that the end date is missing;
   * a blank expiry_date in certification-replies.csv means the certificate does not expire — some older certificates are time-unlimited.
* No money appears anywhere. We do not record fees, salaries or contract values in the credentialing file.
* Files are UTF-8 with Unix line endings. Values are quoted only when they contain a comma.
The three joins that matter
1. Everything on the applicant side joins on application_id, and on revision where the fact belongs to a revision. Entries, credentials, privilege requests and disclosures all restate on each revision, so always filter to the revision you are working.
2. The Washington board export carries no practitioner identifier. It never has. I join it to an application on lastname, firstname, middlename and birthyear. I have checked that no two rows in any one export share those four values, so the join gives you at most one row. An applicant with no row in that file holds no Washington credential. The absence is the answer, not a data problem.
3. A referee with no row in peer-reference-replies.csv has not replied. Silence produces no record. You can see it only by looking at the requests in verification-attempts.csv and finding no reply against them.
The Washington export's own columns
I pass that file through as the board publishes it and add one column. The board's twelve are credentialnumber, credentialtype, status, firstissuedate, lastissuedate, expirationdate, ceduedate, actiontaken, birthyear, firstname, middlename, lastname. Mine is lookup_date — the day I ran the lookup. It is my own act, not a source's reply, so the usability window is not applied to it.
Two of the board's columns are easy to misread:
* ceduedate is a continuing-education due date. We do not use it. Continuing education is handled outside this procedure and it has nothing to do with whether a licence is valid.
* actiontaken says the board has acted. It does not say what the action was. For that you need the board's written reply, which arrives as a document, not in this file. A Yes here is a reason to go and read; it is not a conclusion.
The first export carries the board's whole file for our county — 435 rows — so you can see what an ordinary population looks like. The second and third carry only a re-lookup of the practitioners whose files are open, because that is all I re-run.
How often anything is actually wrong
I want to say this plainly, because a small sample of credentialing files can leave the wrong impression.
In the board's population, action against a credential is rare. In the 435-row export you have: 431 rows say No, 3 say Yes, and 1 says Pending. That is 0.69% Yes and 0.23% Pending, and it is the shape of the real thing — the overwhelming majority of licensed practitioners have a clean board record, and any tool that expects otherwise will be wrong almost every time it fires.
The applicants in these batches are a different matter, and deliberately so. This is a teaching set. I have put every situation the procedure has a rule for into these three exports on purpose, so the run has something to exercise: a restricted licence, an unexplained gap, a school that closed, a referee who never answers, a certificate that lapsed, a decision against the wrong revision. A real nine weeks of intake would be far quieter than this. Do not read the applicant set as a base rate. Read it as a checklist that happens to be shaped like a caseload.
The clean files are genuinely clean. If your tool raises something on one of them, it is your tool.
What I do not export
My own queue, my own statuses and my own conclusions. This export is the evidence, not my reading of it. What is complete, what is outstanding, what is presentable and what is owed to whom is the work — it is not in the folder, and it should not be.
Referee addresses. The export carries no address column for peer referees. The working-address half of completeness condition 7 is checked by my office outside the export, so a run assesses condition 7 on the named referees alone and records the address check as not assessable from the export — neither met nor failed.
9. The committee protocol
The medical staff recommends; the Governing Body approves. The manual, Section 1:
"The Governing Body has the authority to grant, modify, or deny medical staff membership and clinical privileges to LPs"
and the Executive Committee of the Medical Staff
"proposes a recommendation through the clinical director (CD) and the chief executive officer (CEO) or their designee to the Governing Body"
Section 7:
"The GB or a delegated GB committee retains the final authority to grant, renew, or deny privileges after considering the recommendations of the medical staff"
Section 12, on who may record what:
"All signatories should utilize a "recommend" selection, with only the Chair of the GB or their designee using the "approval" selection."
A recommendation is not an approval. A record from the Credentials Committee or the Executive Committee of the Medical Staff that carries the word "approved" is still a recommendation, because those bodies cannot approve. Only the Governing Body chair, or the designee named in authority-roster.md, records an approval.
Larkhollow rule — what makes a decision admissible. All five, checked against the roster and the packet and never against the record's own claim:
1. the body is one that may record that outcome;
2. the signatory held the named role on the decision date, per authority-roster.md;
3. the decision names the same applicant and the same application revision as the presentable packet;
4. a presentable packet existed for that revision before the decision date;
5. the outcome is one of approved, approved-with-conditions, deferred-pending-information, denied, recommended, not recommended, and every outcome other than a plain approval carries a reason.
A decision that fails any of these is not a decision. It is recorded as received, raised to the Medical Services Professional, and nothing activates on it.
Larkhollow rule — a decision against a superseded revision. It does not authorize the current revision. It stays in the file as history against the revision it named, and it is never deleted.
Larkhollow rule — two decisions for one revision. A second decision for the same application revision is admissible only when it names the earlier decision it supersedes. Without that reference it is a duplicate, it is inadmissible, and it is raised to the Medical Services Professional. The first decision continues to stand.
Larkhollow rule — which outcomes carry a reason, and what counts as a second decision. recommended is the positive outcome of a body that cannot approve (the Credentials Committee or the Executive Committee of the Medical Staff); like a plain approval it carries no reason, while not recommended carries one, as do approval-with-conditions, deferral and denial. The two-decisions rule above applies to a second decision of the same body for the same revision: a recommendation followed by the Governing Body's decision on the same revision is the normal sequence, not a duplicate, and a second recommendation is never a duplicate — so in practice it is a second Governing Body decision for the same revision that must name the earlier one it supersedes.
Larkhollow rule — deferral. A deferral names the information it waits for. The office chases exactly that, and the file does not advance while it waits.
10. Activation and the appointment cycle
The manual, Section 5:
"The provider cannot provide patient care services until the practitioner has been approved for their next appointment and privilege cycle."
and Section 15:
"The GB needs to approve a provider's privileges and/or appointment on or before the"
expiry date, to prevent a lapse; and a later start date is permitted when the body records it:
"Yes, if the GB makes the notation in their final notes when they sign off on the signature pages in Virtual Committee."
Larkhollow rule — activation. On an admitted Governing Body approval, the office records the appointment and activates exactly the privilege groups named in the decision — never more, and never a group that was requested but not granted. Privileges become active on the effective date the decision records, or on the decision date when the decision records no separate effective date. Nothing is active before that day. The cycle end is computed as in check 1.
Larkhollow rule — approve with conditions. An approval with conditions activates the approved privilege groups on the normal rule above, and records each condition as a monitored condition with its own due date. A condition is satisfied only by a record naming it. A condition still unmet on its due date becomes a finding to the Clinical Director.
Monitored conditions do not block activation. A licence expiring inside the cycle, and a condition attached to an approval, are both tracked to their due dates while the privileges run.
11. Re-entry: when something lands on work already done
The manual, Section 15:
"The MSP must verify all expirables upon expiration and place the documentation in the file."
"must continue monitoring expirables even during the review process and always provide the most current information"
A file waiting for a committee is not frozen. Credentials go on expiring underneath it and we go on watching them.
Larkhollow rule — the five re-entry triggers, and what each affects:
What arrives
	What it affects
	A new application revision
	intake and completeness run again on the new revision; the prior revision stays in the file; any packet readiness bound to the prior revision is gone
	New evidence on an element — a reply, a reclassification, a corrected date
	that element re-opens; packet readiness is gone; other elements are untouched
	A credential expires or is renewed
	the licensure check re-runs on the new dates; a re-verification is placed in the file
	A decision that is not admissible, or that names a superseded revision
	nothing activates; the record is raised, kept, and never deleted
	A withdrawal by the applicant, or a discontinuation by the Clinical Director
	the file ends with the terminal reason recorded. It is never labelled appointed
	A re-entry adds an occurrence to the file. It does not overwrite the occurrence before it.

